-- 공모주 청약 추천 전략 (2026-10-15 사용자 "공모주는 청약 기준 추천 전략이 필요", aiDoc/ipo-subscription-strategy.md) — ipo 모듈 소유.
--
-- ① ipo_deals: 청약 추천 재료와 결과.
--    - 상장 직후 유통가능물량 비율·상장예정주식수 — 증권신고서 본문에서 읽는다(FloatSharesParser).
--    - 청약 추천 등급(비례까지·균등만·패스·판단 보류)과 점수 — 권고 칸(recommendation)은 RECOMMEND/SKIP/PENDING 그대로 둔다(화면·API 호환).
--    - 상장일 시가·종가 — 15:40 키움 일봉(시장 분위기 재료).
-- ② ipo_listing_history: 회사마다 한 행 — 판단 재료와 상장일 성과. 추천의 시장 맥락(직전 20건 확약 중앙값, 직전 상장 5곳 상장일
--    종가 평균)을 여기서 센다. 2025-04~2026-10 공모주 85곳을 넣는다(source=SEED) — scripts/fetch_ipo_history.py로 모은 검증 자료
--    (DART [발행조건확정]·투자설명서, 상장일 시세는 수정주가가 아닌 값)를 앱과 같은 파서로 읽은 값이다. 오늘(10/15) 상장한 곳의 시세는
--    넣지 않는다 — 앱이 다음 15:40에 키움 일봉으로 채운다.
ALTER TABLE ipo_deals
    ADD COLUMN float_ratio    NUMERIC(6, 4),    -- 상장 직후 유통가능물량 ÷ 상장예정주식수
    ADD COLUMN listed_shares  BIGINT,           -- 상장예정주식수
    ADD COLUMN float_rcept_no VARCHAR(20),      -- 유통가능물량을 읽은 신고서
    ADD COLUMN advice_grade   VARCHAR(16),      -- PROPORTIONAL·EQUAL_ONLY·PASS·PENDING
    ADD COLUMN advice_score   INTEGER,
    ADD COLUMN listing_open   NUMERIC(19, 4),
    ADD COLUMN listing_close  NUMERIC(19, 4);

COMMENT ON COLUMN ipo_deals.float_ratio IS '상장 직후 유통가능물량 비율(0~1) — 증권신고서 본문(V19)';
COMMENT ON COLUMN ipo_deals.advice_grade IS '청약 추천 등급 — 비례까지(PROPORTIONAL)·균등만(EQUAL_ONLY)·패스(PASS)·판단 보류(PENDING)(V19)';

CREATE TABLE ipo_listing_history (
    corp_code        VARCHAR(16)    PRIMARY KEY,
    corp_name        VARCHAR(128)   NOT NULL,
    stock_code       VARCHAR(12),
    confirmed_on     DATE,                       -- 판단 시점: [발행조건확정] 접수일
    competition_rate NUMERIC(12, 2),             -- 기관경쟁률(N:1의 N)
    lockup_rate      NUMERIC(6, 4),              -- 의무보유확약(신청 수량 기준, 0~1)
    offer_price      NUMERIC(19, 4),             -- 확정 공모가
    band_low         NUMERIC(19, 4),
    band_high        NUMERIC(19, 4),
    float_ratio      NUMERIC(6, 4),
    listing_date     DATE,
    listing_open     NUMERIC(19, 4),
    listing_close    NUMERIC(19, 4),
    advice_grade     VARCHAR(16),                -- 앱이 매긴 청약 추천(상장 전 마지막 값 — 전진 검증용). SEED는 비움
    advice_score     INTEGER,
    source           VARCHAR(16)    NOT NULL,    -- SEED(V19), APP
    updated_at       TIMESTAMPTZ    NOT NULL
);

COMMENT ON TABLE ipo_listing_history IS '공모주 판단 재료·상장일 성과 — 청약 추천의 시장 맥락(V19)';

